def get_icon_svg(name: str, color: str = "#60A5FA", size: int = 18) -> str:
    """Return inline SVG HTML string for specified Lucide icon name."""
    template = LUCIDE_SVGS.get(name, LUCIDE_SVGS["Activity"])
    return template.format(color=color, size=size)
